\u043c \\u043f\\u0440\\u043e\\u0435\\u043a\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435\\u043c \\u0441\\u0442\\u0440\\u043e\\u0433\\u043e\\u0433\\u043e \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430 (design-only), \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0440\\u0435\\u0430\\u043b\\u044c\\u043d\\u043e\\u0433\\u043e \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u0430 \\u043d\\u0430 GPU \\u043d\\u0435 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442\\u0441\\u044f \\u0438 \\u043d\\u0435 \\u0437\\u0430\\u044f\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f.\\n\\n---\\n\\n### 2. \\u041a\\u043e\\u043d\\u0446\\u0435\\u043f\\u0442\\u0443\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 \\u0434\\u0440\\u0430\\u0444\\u0442 \\u043f\\u043e\\u0434\\u0445\\u043e\\u0434\\u0430 \\u043a \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0443 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430\\n\\u0426\\u0435\\u043b\\u044c \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430 \\u2014 \\u0438\\u0437\\u043e\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u0438 \\u043a\\u043e\\u043b\\u0438\\u0447\\u0435\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u043e \\u043e\\u0446\\u0435\\u043d\\u0438\\u0442\\u044c \\u0432\\u043a\\u043b\\u0430\\u0434 \\u0434\\u0432\\u0443\\u0445 \\u043a\\u043b\\u044e\\u0447\\u0435\\u0432\\u044b\\u0445 \\u043a\\u043e\\u043c\\u043f\\u043e\\u043d\\u0435\\u043d\\u0442\\u043e\\u0432 InfLLM:\\n1. **Dynamic Context Memory Lookup** (\\u0434\\u0438\\u043d\\u0430\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043f\\u043e\\u0438\\u0441\\u043a \\u0440\\u0435\\u043b\\u0435\\u0432\\u0430\\u043d\\u0442\\u043d\\u044b\\u0445 \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432 \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438).\\n2. **Unit Representations** (\\u0441\\u043f\\u043e\\u0441\\u043e\\u0431\\u044b \\u0440\\u0435\\u043f\\u0440\\u0435\\u0437\\u0435\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438 \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432/\\u044e\\u043d\\u0438\\u0442\\u043e\\u0432 \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u043d\\u043e\\u0439 \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438).\\n\\n\\u0414\\u043b\\u044f \\u044d\\u0442\\u043e\\u0433\\u043e \\u043f\\u043b\\u0430\\u043d\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u043c\\u043d\\u043e\\u0433\\u043e\\u0444\\u0430\\u043a\\u0442\\u043e\\u0440\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430 \\u0441 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u0438\\u0440\\u0443\\u0435\\u043c\\u044b\\u043c\\u0438 \\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u044f\\u043c\\u0438:\\n\\n#### \\u0410. \\u0410\\u043d\\u0430\\u043b\\u0438\\u0437 Dynamic Context Memory Lookup (\\u0424\\u0430\\u043a\\u0442\\u043e\\u0440 \\u043f\\u043e\\u0438\\u0441\\u043a\\u0430)\\n- **\\u0418\\u0441\\u0441\\u043b\\u0435\\u0434\\u0443\\u0435\\u043c\\u044b\\u0439 \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0437\\u043c**: \\u0414\\u0438\\u043d\\u0430\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0441\\u043a\\u043e\\u0440\\u0438\\u043d\\u0433 \\u0440\\u0435\\u043b\\u0435\\u0432\\u0430\\u043d\\u0442\\u043d\\u043e\\u0441\\u0442\\u0438 \\u043c\\u0435\\u0436\\u0434\\u0443 \\u0442\\u0435\\u043a\\u0443\\u0449\\u0438\\u043c \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u043e\\u043c/\\u0437\\u0430\\u043f\\u0440\\u043e\\u0441\\u043e\\u043c \\u0438 \\u0431\\u043b\\u043e\\u043a\\u0430\\u043c\\u0438 \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438 \\u0434\\u043b\\u044f \\u043f\\u043e\\u0434\\u0433\\u0440\\u0443\\u0437\\u043a\\u0438 \\u0442\\u043e\\u043f-$K$ \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432 \\u0432 \\u0430\\u043a\\u0442\\u0438\\u0432\\u043d\\u044b\\u0439 \\u043a\\u044d\\u0448.\\n- **\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u044b \\u0438 \\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u0438**:\\n  1. *Full dynamic lookup* (\\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0439 InfLLM): \\u0434\\u0438\\u043d\\u0430\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u043e\\u0442\\u0431\\u043e\\u0440 \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432 \\u043f\\u043e \\u0441\\u0445\\u043e\\u0434\\u0441\\u0442\\u0432\\u0443.\\n  2. *No lookup / Local-only (StreamingLLM baseline)*: \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e attention sinks + \\u043b\\u043e\\u043a\\u0430\\u043b\\u044c\\u043d\\u043e\\u0435 \\u0441\\u043a\\u043e\\u043b\\u044c\\u0437\\u044f\\u0449\\u0435\\u0435 \\u043e\\u043a\\u043d\\u043e (\\u043f\\u0430\\u043c\\u044f\\u0442\\u044c \\u043e\\u0442\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0430).\\n  3. *Static recency / FIFO memory*: \\u043f\\u043e\\u0434\\u0433\\u0440\\u0443\\u0437\\u043a\\u0430 \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u043d\\u0438\\u0445 \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432 \\u0431\\u0435\\u0437 \\u0441\\u0435\\u043c\\u0430\\u043d\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0433\\u043e \\u043f\\u043e\\u0438\\u0441\\u043a\\u0430.\\n  4. *Uniform / Strided sampling*: \\u0440\\u0430\\u0432\\u043d\\u043e\\u043c\\u0435\\u0440\\u043d\\u0430\\u044f \\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0430 \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432 \\u043f\\u043e \\u0434\\u043b\\u0438\\u043d\\u0435 \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u0430.\\n  5. *Random lookup*: \\u0441\\u043b\\u0443\\u0447\\u0430\\u0439\\u043d\\u0430\\u044f \\u0432\\u044b\\u0431\\u043e\\u0440\\u043a\\u0430 $K$ \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432 (\\u043d\\u0435\\u0433\\u0430\\u0442\\u0438\\u0432\\u043d\\u044b\\u0439 \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c).\\n  6. *Full Attention / Oracle KV Cache*: \\u0442\\u043e\\u0447\\u043d\\u043e\\u0435 \\u0432\\u043d\\u0438\\u043c\\u0430\\u043d\\u0438\\u0435 \\u043a\\u043e \\u0432\\u0441\\u0435\\u043c \\u0442\\u043e\\u043a\\u0435\\u043d\\u0430\\u043c \\u0431\\u0435\\u0437 \\u0441\\u0436\\u0430\\u0442\\u0438\\u044f/\\u0432\\u044b\\u0442\\u0435\\u0441\\u043d\\u0435\\u043d\\u0438\\u044f (\\u0432\\u0435\\u0440\\u0445\\u043d\\u044f\\u044f \\u0433\\u0440\\u0430\\u043d\\u0438\\u0446\\u0430 \\u043a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u0430).\\n  7. *Lookup Granularity / Frequency*: \\u043e\\u0431\\u043d\\u043e\\u0432\\u043b\\u0435\\u043d\\u0438\\u0435 \\u0432\\u044b\\u0431\\u0440\\u0430\\u043d\\u043d\\u044b\\u0445 \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432 \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 \\u0442\\u043e\\u043a\\u0435\\u043d vs \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 \\u0431\\u043b\\u043e\\u043a \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432.\\n\\n#### \\u0411. \\u0410\\u043d\\u0430\\u043b\\u0438\\u0437 Unit Representations (\\u0424\\u0430\\u043a\\u0442\\u043e\\u0440 \\u0440\\u0435\\u043f\\u0440\\u0435\\u0437\\u0435\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438 \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432)\\n- **\\u0418\\u0441\\u0441\\u043b\\u0435\\u0434\\u0443\\u0435\\u043c\\u044b\\u0439 \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0437\\u043c**: \\u041a\\u0430\\u043a \\u0438\\u043c\\u0435\\u043d\\u043d\\u043e \\u043a\\u043e\\u0434\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u0431\\u043b\\u043e\\u043a \\u0434\\u043b\\u0438\\u043d\\u044b $L$ \\u0432 \\u043a\\u043e\\u043c\\u043f\\u0430\\u043a\\u0442\\u043d\\u044b\\u0439 \\u0432\\u0435\\u043a\\u0442\\u043e\\u0440 \\u0434\\u043b\\u044f \\u0438\\u043d\\u0434\\u0435\\u043a\\u0441\\u0430\\u0446\\u0438\\u0438 \\u0438 \\u043f\\u043e\\u0438\\u0441\\u043a\\u0430.\\n- **\\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u044b \\u0440\\u0435\\u043f\\u0440\\u0435\\u0437\\u0435\\u043d\\u0442\\u0430\\u0446\\u0438\\u0439**:\\n  1. *Mean-pooling of Keys* (\\u0443\\u0441\\u0440\\u0435\\u0434\\u043d\\u0435\\u043d\\u0438\\u0435 key-\\u0432\\u0435\\u043a\\u0442\\u043e\\u0440\\u043e\\u0432 \\u0431\\u043b\\u043e\\u043a\\u0430 \\u2014 \\u0431\\u0430\\u0437\\u043e\\u0432\\u044b\\u0439 \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442 InfLLM).\\n  2. *First token / Last token Key* (\\u043a\\u0440\\u0430\\u0435\\u0432\\u044b\\u0435 \\u0442\\u043e\\u043a\\u0435\\u043d\\u044b \\u0431\\u043b\\u043e\\u043a\\u0430).\\n  3. *Max-pooling of Keys* (\\u043f\\u043e\\u043a\\u043e\\u043c\\u043f\\u043e\\u043d\\u0435\\u043d\\u0442\\u043d\\u044b\\u0439 \\u043c\\u0430\\u043a\\u0441\\u0438\\u043c\\u0443\\u043c).\\n  4. *Norm-weighted / Attention-weighted pooling* (\\u0432\\u0437\\u0432\\u0435\\u0448\\u0438\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432 \\u0441 \\u043d\\u0430\\u0438\\u0431\\u043e\\u043b\\u044c\\u0448\\u0435\\u0439 \\u043d\\u043e\\u0440\\u043c\\u043e\\u0439 \\u0438\\u043b\\u0438 \\u043b\\u043e\\u043a\\u0430\\u043b\\u044c\\u043d\\u044b\\u043c \\u0432\\u0435\\u0441\\u043e\\u043c \\u0432\\u043d\\u0438\\u043c\\u0430\\u043d\\u0438\\u044f).\\n  5. *Ablation \\u043f\\u043e \\u0440\\u0430\\u0437\\u043c\\u0435\\u0440\\u0443 \\u044e\\u043d\\u0438\\u0442\\u0430 ($L$)*: $L \\\\in \\\\{16, 32, 64, 128, 256\\\\}$ \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432 \\u0434\\u043b\\u044f \\u0432\\u044b\\u044f\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u0431\\u0430\\u043b\\u0430\\u043d\\u0441\\u0430 \\u043c\\u0435\\u0436\\u0434\\u0443 \\u0441\\u0435\\u043c\\u0430\\u043d\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u043c \\u0440\\u0430\\u0437\\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435\\u043c \\u0438 \\u0432\\u044b\\u0447\\u0438\\u0441\\u043b\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u044b\\u043c\\u0438 \\u0437\\u0430\\u0442\\u0440\\u0430\\u0442\\u0430\\u043c\\u0438.\\n\\n#### \\u0412. \\u0411\\u0435\\u043d\\u0447\\u043c\\u0430\\u0440\\u043a\\u0438 \\u0438 \\u0441\\u043f\\u0435\\u043a\\u0442\\u0440 long-context \\u0437\\u0430\\u0434\\u0430\\u0447\\n\\u041e\\u0446\\u0435\\u043d\\u043a\\u0430 \\u0434\\u043e\\u043b\\u0436\\u043d\\u0430 \\u043f\\u043e\\u043a\\u0440\\u044b\\u0432\\u0430\\u0442\\u044c \\u0440\\u0430\\u0437\\u043b\\u0438\\u0447\\u043d\\u044b\\u0435 \\u0442\\u0438\\u043f\\u044b \\u043a\\u043e\\u0433\\u043d\\u0438\\u0442\\u0438\\u0432\\u043d\\u044b\\u0445 \\u043d\\u0430\\u0433\\u0440\\u0443\\u0437\\u043e\\u043a \\u043d\\u0430 \\u043f\\u0430\\u043c\\u044f\\u0442\\u044c:\\n1. **\\u0421\\u0442\\u0440\\u0435\\u0441\\u0441-\\u0442\\u0435\\u0441\\u0442\\u044b \\u043d\\u0430 \\u043f\\u043e\\u0438\\u0441\\u043a \\u0444\\u0430\\u043a\\u0442\\u043e\\u0432 (Retrieval-intensive)**: Single-Needle \\u0438 Multi-Needle in a Haystack (\\u043f\\u0440\\u043e\\u0432\\u0435\\u0440\\u043a\\u0430 \\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0438 \\u043a \\u043f\\u043e\\u0438\\u0441\\u043a\\u0443 \\u0442\\u043e\\u0447\\u0435\\u0447\\u043d\\u043e\\u0439 \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u0438 \\u043d\\u0430 \\u0433\\u043b\\u0443\\u0431\\u0438\\u043d\\u0430\\u0445 \\u0434\\u043e 64k/128k).\\n2. **\\u041c\\u043d\\u043e\\u0433\\u043e\\u0448\\u0430\\u0433\\u043e\\u0432\\u043e\\u0435 \\u0440\\u0430\\u0441\\u0441\\u0443\\u0436\\u0434\\u0435\\u043d\\u0438\\u0435 \\u0438 QA \\u043f\\u043e \\u0434\\u043b\\u0438\\u043d\\u043d\\u044b\\u043c \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u0430\\u043c (Reasoning & QA)**: LongBench / L-Eval (\\u0437\\u0430\\u0434\\u0430\\u0447\\u0438 \\u0432\\u0440\\u043e\\u0434\\u0435 NarrativeQA, Qasper, HotpotQA).\\n3. **\\u0410\\u0433\\u0440\\u0435\\u0433\\u0430\\u0446\\u0438\\u044f \\u0438\\u043d\\u0444\\u043e\\u0440\\u043c\\u0430\\u0446\\u0438\\u0438 \\u0438 \\u0441\\u0443\\u043c\\u043c\\u0430\\u0440\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f (Global context aggregation)**: GovReport, Multi-News.\\n4. **\\u041a\\u043e\\u0434\\u043e\\u0432\\u044b\\u0435 \\u0437\\u0430\\u0432\\u0438\\u0441\\u0438\\u043c\\u043e\\u0441\\u0442\\u0438 (Code understanding)**: RepoBench / L-Eval (\\u043f\\u043e\\u0438\\u0441\\u043a \\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u0438\\u0439 \\u0444\\u0443\\u043d\\u043a\\u0446\\u0438\\u0439 \\u0447\\u0435\\u0440\\u0435\\u0437 \\u0434\\u043b\\u0438\\u043d\\u043d\\u044b\\u0435 \\u0444\\u0430\\u0439\\u043b\\u044b).\\n5. **\\u042f\\u0437\\u044b\\u043a\\u043e\\u0432\\u043e\\u0435 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 (Perplexity extrapolation)**: PG-19 / Proof-pile \\u043f\\u0440\\u0438 \\u043c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u0438 \\u0434\\u043b\\u0438\\u043d\\u044b \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u0430.\\n\\n#### \\u0413. \\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438\\n- \\u041a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u043e: Task-specific metrics (Accuracy/F1/ROUGE), Retrieval Recall (\\u043d\\u0430\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u0442\\u043e\\u0447\\u043d\\u043e \\u0432\\u044b\\u0431\\u0440\\u0430\\u043d\\u043d\\u044b\\u0439 \\u0431\\u043b\\u043e\\u043a \\u0441\\u043e\\u0432\\u043f\\u0430\\u043b \\u0441 \\u0431\\u043b\\u043e\\u043a\\u043e\\u043c, \\u0441\\u043e\\u0434\\u0435\\u0440\\u0436\\u0430\\u0449\\u0438\\u043c ground-truth \\u043e\\u0442\\u0432\\u0435\\u0442), Perplexity.\\n- \\u0412\\u044b\\u0447\\u0438\\u0441\\u043b\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u0430\\u044f \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u0438\\u0432\\u043d\\u043e\\u0441\\u0442\\u044c: Latency \\u0434\\u0435\\u043a\\u043e\\u0434\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f (ms/token), \\u043f\\u0438\\u043a\\u043e\\u0432\\u043e\\u0435 \\u043f\\u043e\\u0442\\u0440\\u0435\\u0431\\u043b\\u0435\\u043d\\u0438\\u0435 \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438 (VRAM), FLOPs \\u043d\\u0430 lookup.\\n\\n---\\n\\n### 3. \\u041a\\u043b\\u044e\\u0447\\u0435\\u0432\\u044b\\u0435 \\u0434\\u043e\\u043f\\u0443\\u0449\\u0435\\u043d\\u0438\\u044f (Assumptions)\\n1. **Training-free \\u043f\\u0430\\u0440\\u0430\\u0434\\u0438\\u0433\\u043c\\u0430**: InfLLM \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u043a \\u043f\\u0440\\u0435\\u0434\\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u043d\\u044b\\u043c \\u0437\\u0430\\u043c\\u043e\\u0440\\u043e\\u0436\\u0435\\u043d\\u043d\\u044b\\u043c \\u043c\\u043e\\u0434\\u0435\\u043b\\u044f\\u043c (LLaMA-3, Mistral \\u0438 \\u0442.\\u043f.) \\u0431\\u0435\\u0437 \\u0434\\u043e\\u043e\\u0431\\u0443\\u0447\\u0435\\u043d\\u0438\\u044f \\u0432\\u0435\\u0441\\u043e\\u0432; \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442\\u044b \\u0438\\u0437\\u043c\\u0435\\u0440\\u044f\\u044e\\u0442\\u0441\\u044f \\u0441\\u0443\\u0433\\u0443\\u0431\\u043e \\u043d\\u0430 \\u0443\\u0440\\u043e\\u0432\\u043d\\u0435 \\u043c\\u0435\\u0445\\u0430\\u043d\\u0438\\u0437\\u043c\\u0430 \\u0443\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f KV-\\u043a\\u044d\\u0448\\u0435\\u043c.\\n2. **\\u0421\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u0430 \\u043f\\u0430\\u043c\\u044f\\u0442\\u0438**: \\u041a\\u044d\\u0448 \\u0440\\u0430\\u0437\\u0434\\u0435\\u043b\\u0435\\u043d \\u043d\\u0430 \\u0442\\u0440\\u0438 \\u0437\\u043e\\u043d\\u044b: Attention Sinks (\\u043d\\u0430\\u0447\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0442\\u043e\\u043a\\u0435\\u043d\\u044b), Local Window (\\u043d\\u0435\\u0434\\u0430\\u0432\\u043d\\u0438\\u0435 \\u0442\\u043e\\u043a\\u0435\\u043d\\u044b) \\u0438 Context Memory (\\u043e\\u0444\\u0444\\u043b\\u043e\\u0430\\u0434 \\u0431\\u043b\\u043e\\u043a\\u043e\\u0432).\\n3. **\\u0421\\u0432\\u044f\\u0437\\u0430\\u043d\\u043d\\u043e\\u0441\\u0442\\u044c \\u0440\\u0435\\u043f\\u0440\\u0435\\u0437\\u0435\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438 \\u0438 \\u043f\\u043e\\u0438\\u0441\\u043a\\u0430**: \\u041a\\u0430\\u0447\\u0435\\u0441\\u0442\\u0432\\u043e dynamic lookup \\u043d\\u0430\\u043f\\u0440\\u044f\\u043c\\u0443\\u044e \\u043b\\u0438\\u043c\\u0438\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043e \\u0442\\u043e\\u0447\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e \\u0440\\u0435\\u043f\\u0440\\u0435\\u0437\\u0435\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438 \\u044e\\u043d\\u0438\\u0442\\u0430: \\u0435\\u0441\\u043b\\u0438 \\u0432\\u0435\\u043a\\u0442\\u043e\\u0440 \\u0431\\u043b\\u043e\\u043a\\u0430 \\u0442\\u0435\\u0440\\u044f\\u0435\\u0442 \\u0441\\u0435\\u043c\\u0430\\u043d\\u0442\\u0438\\u043a\\u0443 \\u043a\\u043b\\u044e\\u0447\\u0435\\u0432\\u044b\\u0445 \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432, \\u043f\\u043e\\u0438\\u0441\\u043a \\u0434\\u0435\\u0433\\u0440\\u0430\\u0434\\u0438\\u0440\\u0443\\u0435\\u0442.\\n4. **\\u0413\\u0438\\u043f\\u043e\\u0442\\u0435\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0430\\u043f\\u043f\\u0430\\u0440\\u0430\\u0442\\u043d\\u0430\\u044f \\u0441\\u0440\\u0435\\u0434\\u0430**: \\u0414\\u043b\\u044f \\u043f\\u0440\\u043e\\u0435\\u043a\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u043b\\u0430\\u0433\\u0430\\u0435\\u0442\\u0441\\u044f \\u0441\\u0442\\u0430\\u043d\\u0434\\u0430\\u0440\\u0442\\u043d\\u0430\\u044f \\u043d\\u043e\\u0434\\u0430 (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, 8x A100/H100 80GB), \\u0434\\u043e\\u0441\\u0442\\u0430\\u0442\\u043e\\u0447\\u043d\\u0430\\u044f \\u0434\\u043b\\u044f \\u0437\\u0430\\u043f\\u0443\\u0441\\u043a\\u0430 \\u0434\\u043b\\u0438\\u043d\\u043d\\u044b\\u0445 \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u043e\\u0432 (\\u0434\\u043e 128k+).\\n\\n---\\n\\n### 4. \\u041d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0435\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 \\u0438 \\u043e\\u0442\\u043a\\u0440\\u044b\\u0442\\u044b\\u0435 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u044b (Uncertainties)\\n1. **\\u0412\\u044b\\u0431\\u043e\\u0440 \\u0431\\u0430\\u0437\\u043e\\u0432\\u044b\\u0445 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439**: \\u0421\\u043b\\u0435\\u0434\\u0443\\u0435\\u0442 \\u043b\\u0438 \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u043e\\u0434\\u043d\\u0443 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044c (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, LLaMA-3-8B-Instruct) \\u0438\\u043b\\u0438 \\u043f\\u0430\\u0440\\u0430\\u043b\\u043b\\u0435\\u043b\\u044c\\u043d\\u043e \\u0441\\u0440\\u0430\\u0432\\u043d\\u0438\\u0432\\u0430\\u0442\\u044c \\u043d\\u0435\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440 (\\u043d\\u0430\\u043f\\u0440\\u0438\\u043c\\u0435\\u0440, RoPE \\u0441 \\u0440\\u0430\\u0437\\u043d\\u043e\\u0439 \\u0431\\u0430\\u0437\\u043e\\u0439 / Mistral \\u0441 sliding window attention)?\\n2. **\\u041f\\u0440\\u0435\\u0434\\u0435\\u043b\\u044c\\u043d\\u0430\\u044f \\u0434\\u043b\\u0438\\u043d\\u0430 \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u0430**: \\u041e\\u043f\\u0442\\u0438\\u043c\\u0430\\u043b\\u044c\\u043d\\u043e \\u043b\\u0438 \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0438\\u0442\\u044c \\u0442\\u0435\\u0441\\u0442\\u043e\\u0432\\u0443\\u044e \\u0433\\u043b\\u0443\\u0431\\u0438\\u043d\\u0443 64k-128k \\u0442\\u043e\\u043a\\u0435\\u043d\\u0430\\u043c\\u0438 \\u0438\\u043b\\u0438 \\u0440\\u0430\\u0441\\u0441\\u043c\\u043e\\u0442\\u0440\\u0435\\u0442\\u044c \\u044d\\u043a\\u0441\\u0442\\u0440\\u0435\\u043c\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u043c\\u0430\\u0441\\u0448\\u0442\\u0430\\u0431\\u044b (\\u0434\\u043e 512k-1M \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432)?\\n3. **\\u0414\\u0435\\u0442\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f \\u0430\\u043b\\u0433\\u043e\\u0440\\u0438\\u0442\\u043c\\u0430 \\u0440\\u0435\\u043f\\u0440\\u0435\\u0437\\u0435\\u043d\\u0442\\u0430\\u0446\\u0438\\u0438**: \\u0424\\u043e\\u043a\\u0443\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c\\u0441\\u044f \\u043b\\u0438 \\u0441\\u0442\\u0440\\u043e\\u0433\\u043e \\u043d\\u0430 \\u0432\\u0435\\u043a\\u0442\\u043e\\u0440\\u043d\\u044b\\u0445 \\u0441\\u0432\\u0435\\u0440\\u0442\\u043a\\u0430\\u0445 \\u043a\\u043b\\u044e\\u0447\\u0435\\u0439 (Keys) \\u0438\\u043b\\u0438 \\u0442\\u0430\\u043a\\u0436\\u0435 \\u0440\\u0430\\u0441\\u0441\\u043c\\u043e\\u0442\\u0440\\u0435\\u0442\\u044c \\u0430\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u044b \\u0441 \\u0440\\u0435\\u043f\\u0440\\u0435\\u0437\\u0435\\u043d\\u0442\\u0430\\u0446\\u0438\\u0435\\u0439 \\u0447\\u0435\\u0440\\u0435\\u0437 \\u0441\\u043a\\u0440\\u044b\\u0442\\u044b\\u0435 \\u0441\\u043e\\u0441\\u0442\\u043e\\u044f\\u043d\\u0438\\u044f (Hidden states)?\\n\\n\\u0413\\u043e\\u0442\\u043e\\u0432 \\u043f\\u0435\\u0440\\u0435\\u0439\\u0442\\u0438 \\u043a \\u0434\\u0435\\u0442\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 \\u043f\\u043e\\u043b\\u043d\\u043e\\u0433\\u043e \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0430 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430 \\u043f\\u043e\\u0441\\u043b\\u0435 \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f \\u0438\\u043b\\u0438 \\u043a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0442\\u0438\\u0440\\u043e\\u0432\\u043a\\u0438 \\u0444\\u043e\\u043a\\u0443\\u0441\\u0430.\", \"summary\": \"\\u0418\\u043d\\u0441\\u043f\\u0435\\u043a\\u0446\\u0438\\u044f \\u043e\\u043a\\u0440\\u0443\\u0436\\u0435\\u043d\\u0438\\u044f \\u0438 \\u0434\\u0440\\u0430\\u0444\\u0442 \\u043f\\u043e\\u0434\\u0445\\u043e\\u0434\\u0430 \\u043a \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0443 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442\\u0430\", \"assumptions\": [\"InfLLM \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u044f\\u0435\\u0